import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import {PawPrint,MagnifyingGlass,Plus,CaretDown,CaretLeft,CaretRight,Check,Circle,CircleNotch,Camera,X,CalendarBlank,Users,ClipboardText,House,GearSix,ArrowRight,Clock,MapPin,WarningCircle,DownloadSimple,Copy,CheckCircle,FileText,Eye,UploadSimple,Phone,Globe,Stack,Pen,SealCheck} from '@phosphor-icons/react';
import {uid,newVisit,validateService,publishReport,addDays,weekOf,saveVisitEdit} from './domain.js';
import {RELEASE_DATE,STORAGE_KEY,petImage,taskNames,templates,migrateState,localizedSeed,localizeDemoContent,makeClient,saveClient,dateText,plainReport,compressPhoto} from './international.js';
import {VisitEditor,PhotoEditor} from './editors.jsx';
import {ExportPanel} from './ExportPanel.jsx';
import {useMobile,MobileWorkspace,MobileSchedule,MobileSettings} from './Mobile.jsx';
const Language=createContext('zh');
const todayDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const useCopy=()=>{const lang=useContext(Language);return (en,zh)=>lang==='en'?en:zh;};
const timeNow=()=>new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const initialQuery=()=>typeof location==='undefined'?new URLSearchParams():new URLSearchParams(location.search);
const navs=[['work','Workspace','工作台',House],['schedule','Schedule','服务排期',CalendarBlank],['clients','Clients & pets','客户与宠物',Users],['reports','Care reports','服务报告',ClipboardText]];
function initialState(lang,design){if(design)return localizedSeed(lang);try{const d=JSON.parse(localStorage.getItem(STORAGE_KEY));return d?localizeDemoContent(migrateState(d),lang):localizedSeed(lang)}catch{return localizedSeed(lang)}}
function StatusIcon({status}){return status==='completed'?<CheckCircle weight="fill" className="success"/>:status==='active'?<CircleNotch className="active"/>:<Circle className="pending"/>}
export function Modal({title,subtitle,children,onClose,wide=false}){
 const ref=useRef(),closeRef=useRef(onClose);closeRef.current=onClose;const L=useCopy();
 useEffect(()=>{const old=document.activeElement;ref.current?.focus();document.body.style.overflow='hidden';const listener=e=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const list=[...ref.current.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.getClientRects().length);if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',listener);return()=>{document.removeEventListener('keydown',listener);document.body.style.overflow='';old?.focus()}},[]);
 return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" aria-label={L('Close','关闭')} onClick={onClose}><X size={23}/></button></header>{children}</section></div>;
}
function Empty({title,body,children}){return <div className="empty"><PawPrint size={35} weight="light"/><h3>{title}</h3><p>{body}</p>{children}</div>}
export function App(){
 const q=initialQuery();const [lang,setLang]=useState(q.get('lang')==='zh'?'zh':'en');const design=q.get('design')==='1';
 return <Language.Provider value={lang}><Studio key={design?'design':'live'} lang={lang} setLang={setLang} design={design}/></Language.Provider>;
}
function Studio({lang,setLang,design}){
 const mobile=useMobile();const L=useCopy();const [db,setDb]=useState(()=>initialState(lang,design));
 const [tab,setTab]=useState(()=>['work','schedule','clients','reports','settings','plans'].includes(initialQuery().get('view'))?initialQuery().get('view'):'work'),[date,setDate]=useState(()=>db.visits.find(v=>v.id==='v2')?.date||RELEASE_DATE),[selected,setSelected]=useState('v2'),[search,setSearch]=useState(''),[dialog,setDialog]=useState(null),[toast,setToast]=useState(''),[menu,setMenu]=useState(false),[filter,setFilter]=useState('all'),[uploading,setUploading]=useState(false),[saveError,setSaveError]=useState(false),[clientView,setClientView]=useState('clients');
 const photoInput=useRef();const client=id=>db.clients.find(c=>c.id===id);const matches=c=>!search||[c?.name,c?.owner,c?.area,c?.breed,c?.title].some(s=>(s||'').toLowerCase().includes(search.toLowerCase()));
 const visits=db.visits.filter(v=>v.date===date&&v.status!=='cancelled'&&matches(client(v.clientId))).sort((a,b)=>a.time.localeCompare(b.time));
 const visit=visits.find(v=>v.id===selected)||visits.find(v=>v.status==='active')||visits[0];const pet=visit&&(visit.handover||client(visit.clientId));const done=visits.filter(v=>v.status==='completed').length;
 const status=s=>({pending:L('Upcoming','待开始'),active:L('In progress','进行中'),completed:L('Completed','已完成'),cancelled:L('Cancelled','已取消')}[s]);
 useEffect(()=>{if(design)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));setSaveError(false)}catch{setSaveError(true)}},[db,design]);
 useEffect(()=>{document.documentElement.lang=lang==='en'?'en':'zh-CN';document.title=L('Pawly · Every visit, thoughtfully done.','Pawly · 把每一次照顾，放在心上');const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState({},'',url);},[lang]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3800);return()=>clearTimeout(t)},[toast]);
 const navigate=t=>{setTab(t);setMenu(false);setSearch('');const url=new URL(location.href);url.searchParams.set('view',t);history.replaceState({},'',url);window.scrollTo({top:0,behavior:'instant'});};
 const openVisit=v=>{setDate(v.date);setSelected(v.id);navigate('work')};
 const patchVisit=patch=>{if(!visit||visit.status==='completed')return;setDb(s=>({...s,visits:s.visits.map(v=>v.id===visit.id?{...v,...patch,savedAt:timeNow()}:v)}))};
 const download=(filename,contents,type='application/json')=>{const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 const copy=async text=>{try{await navigator.clipboard.writeText(text);setToast(L('Copied. Paste into your message to the owner.','已复制，可粘贴发送给主人。'))}catch{setDialog({type:'copy',text})}};
 async function upload(files){if(!visit||visit.status==='completed'||!files.length)return;if(visit.photos.length+files.length>6)return setToast(L('Add up to 6 photos per visit.','每次到访最多添加6张照片。'));const id=visit.id;setUploading(true);try{const added=[];for(const file of files)added.push(await compressPhoto(file));setDb(s=>({...s,visits:s.visits.map(v=>v.id===id&&v.status!=='completed'?{...v,photos:[...v.photos,...added],savedAt:timeNow()}:v)}));setToast(L('Photos added to this visit.','照片已加入本次记录。'))}catch{setToast(L('Choose JPG, PNG or WebP images under 10 MB.','请选择小于10MB的 JPG、PNG 或 WebP 照片。'))}finally{setUploading(false);if(photoInput.current)photoInput.current.value=''}}
 function publish(id){const v=db.visits.find(v=>v.id===id);if(v.checks.some(x=>!x)&&!v.exception.trim())return setToast(L('Explain any unfinished tasks before publishing.','请说明未完成任务的原因，再发布报告。'));try{const next=publishReport(db,id,timeNow());setDb(next);setDialog({type:'report',id:next.reports.find(r=>r.visitId===id).id});setToast(L('Report published on this device.','报告已发布并保存在本机。'))}catch{setToast(L('Start this visit before publishing a report.','请先开始到访，再发布报告。'))}}
 const openReport=id=>setDialog({type:'report',id});
 const editVisit=(id,section='time')=>setDialog({type:'editVisit',id,section});
 const saveEditedVisit=(draft,sync)=>{try{const next=saveVisitEdit(db,dialog.id,draft,sync,timeNow());if(!design)localStorage.setItem(STORAGE_KEY,JSON.stringify(next));setDb(next);setDate(draft.date);setSelected(dialog.id);setDialog(null);navigate('work');setToast(L('Changes saved. This visit is up to date.','修改已保存，本次服务已更新。'));return '';}catch(e){if(lang!=='en')return e.name==='QuotaExceededError'?'本机空间不足，请减少照片或导出备份后再保存。':e.message;const translations={'这个时间段已有服务，请调整时间。':'This time overlaps another visit. Choose a different time.','请填写宠物名字和主人称呼。':'Enter a pet name and owner name.','请填写1至20项任务，每项不超过80字。':'Enter 1–20 task names, up to 80 characters each.','请说明未完成任务的原因，再保存修订。':'Explain unfinished tasks in Photos & notes before saving.','实际结束时间需要晚于实际开始时间。':'Actual end must be after actual start.','已完成的服务需要填写实际开始和结束时间。':'Enter the actual start and end of this completed visit.','宠物数量请填写1至20的整数。':'Enter a whole number of pets from 1 to 20.'};return translations[e.message]||(e.name==='QuotaExceededError'?'Storage is full. Remove photos or export a backup before saving.':'Check the date, times and required details, then save again.');}};

 const title={work:L('Every visit, thoughtfully done.','把每一次照顾，放在心上'),schedule:L('A little planning. A lot of care.','每一份托付，都有安排'),clients:L('A little guide for every little friend.','记住每一个小习惯'),reports:L('Good care, beautifully recorded.','照顾有记录，牵挂有回应'),settings:L('Make this little studio yours.','让工作台，更顺手'),plans:L('More time for the little things.','把更多时间，留给陪伴')}[tab];
 const headline=(tab==='work'?(db.settings.workTitle||title):title).replace(lang==='zh'?/[。．.]\s*$/:/$^/,'');
 const r=dialog?.id&&db.reports.find(r=>r.id===dialog.id);
 return <div className={'app view-'+tab+' '+(lang==='en'?'english ':'')+(db.settings.compact?'compact':'')}>
 <header className="topbar"><button className="brand" onClick={()=>navigate('work')}>Pawly<PawPrint size={19} weight="fill"/></button><nav className="desktop-nav">{navs.map(([id,en,zh])=><button key={id} className={tab===id?'selected':''} onClick={()=>navigate(id)}>{L(en,zh)}</button>)}</nav><div className="top-actions"><label className="search"><MagnifyingGlass size={20}/><input aria-label={L('Search clients or pets','搜索客户或宠物')} placeholder={L('Search a little friend','搜索客户或宠物名称')} value={search} onChange={e=>setSearch(e.target.value)}/></label><button className="language-button" aria-label={L('Switch to Chinese','切换为英文')} onClick={()=>{const next=lang==='en'?'zh':'en';setDb(s=>localizeDemoContent(s,next));setLang(next);setSearch('');setToast('');setMenu(false);}}><Globe size={17}/>{lang==='en'?'中文':'EN'}</button><button className="studio-settings-link" aria-label={L('Edit studio details','修改工作室资料')} onClick={()=>navigate('settings')}><GearSix size={20}/></button><div className="account"><button className="profile" aria-label={L('Account menu','账户菜单')} aria-expanded={menu} onClick={()=>setMenu(!menu)}><img src={db.settings.avatar||"/assets/sitter.jpg"} alt=""/><span>{db.settings.name}</span><CaretDown size={15}/></button>{menu&&<div className="account-menu"><span>{db.settings.studio}</span><button onClick={()=>navigate('settings')}><GearSix/>{L('Studio settings','工作室设置')}</button><button onClick={()=>navigate('plans')}><SealCheck/>{L('Services & exports','服务与导出')}</button><button onClick={()=>{setMenu(false);setDialog({type:'about'})}}><Eye/>{L('About this preview','体验说明')}</button></div>}</div></div></header>
 <main><section className="page-heading"><div><p className="eyebrow mobile-only">{db.settings.studio}</p><h1 className={lang==='zh'&&headline.length<=24?'single-line-title':''} style={{'--headline-length':headline.length}}>{headline}</h1><p className="heading-sub">{tab==='work'?L(`${visits.length} visits planned · ${done} completed`,`${visits.length} 次到访 · 已完成 ${done} 次`):tab==='clients'?L('Start with a template. Make every detail personal.','从一个参考模板开始，把细节换成真实的托付。'):tab==='schedule'?L('Your week, one thoughtful visit at a time.','从一次到访，到一段安心的陪伴。'):tab==='reports'?L(`${db.reports.length} care reports · Every detail matters.`,`${db.reports.length} 份照顾记录 · 每一份都认真对待`):tab==='plans'?L('Free beta · Excel and PDF exports are available.','内测免费 · 已支持 Excel 和 PDF 导出。'):db.settings.studio}</p></div><div className="heading-actions"><label className="date-control"><CalendarBlank size={17}/><input aria-label={L('View date','查看日期')} type="date" value={date} onChange={e=>{if(e.target.value)setDate(e.target.value)}}/></label><p>{db.settings.tagline??L('Small moments. Thoughtful care.','愿每一只小动物都有被好好照顾的日子。')}</p>{!['settings','plans'].includes(tab)&&<button className="primary pill" aria-label={L('New visit','新建服务')} onClick={()=>setDialog({type:'new',date})}><Plus size={21}/>{L('New visit','新建服务')}</button>}</div></section>
 {tab==='work'&&!db.settings.hideGuide&&<div className="getting-started"><strong>{L('Make this workspace yours','三步开始使用')}</strong><button onClick={()=>visit?editVisit(visit.id,'profile'):navigate('clients')}><span>1</span>{L('Edit pet details','换成你的宠物资料')}</button><button onClick={()=>visit?editVisit(visit.id,'time'):setDialog({type:'new',date})}><span>2</span>{L('Set the visit time','修改服务时间')}</button><button onClick={()=>visit?editVisit(visit.id,'record'):navigate('reports')}><span>3</span>{L('Add photos & notes','上传照片与备注')}</button><button className="icon-button" aria-label={L('Hide getting started','收起上手提示')} onClick={()=>setDb(d=>({...d,settings:{...d.settings,hideGuide:true}}))}><X size={17}/></button></div>}
 {saveError&&<div role="alert" className="error-banner">{L('Device storage is full. Your latest changes are not saved.','本机存储空间不足，最近修改尚未保存。')}<button onClick={()=>download('pawly-backup.json',JSON.stringify(db))}>{L('Export backup','导出备份')}</button></div>}
 {tab==='work'&&mobile&&<MobileWorkspace lang={lang} date={date} setDate={setDate} visits={visits} visit={visit} pet={pet} status={status} onSelect={setSelected} onNew={()=>setDialog({type:'new',date})} onEdit={section=>editVisit(visit.id,section)} onGuide={()=>setDialog({type:'handover',id:visit.clientId,visitId:visit.id})} onPhoto={src=>setDialog({type:'photo',src})} onUpload={upload} uploading={uploading} patchVisit={patchVisit} onReport={()=>visit.status==='completed'?openReport(db.reports.find(r=>r.visitId===visit.id)?.id):setDialog({type:'preview',id:visit.id})} saveError={saveError} Frame={Modal}/> }
 {tab==='work'&&!mobile&&<div className="workbench"><aside className="agenda panel"><div className="agenda-title"><h2>{L('Today’s visits','今日安排')}</h2><div className="tiny-date"><span>{dateText(date,lang)}</span><div><button aria-label={L('Previous day','前一天')} onClick={()=>setDate(addDays(date,-1))}><CaretLeft/></button><button aria-label={L('Next day','后一天')} onClick={()=>setDate(addDays(date,1))}><CaretRight/></button></div></div></div><div className="agenda-list">{visits.map(v=>{const c=v.handover||client(v.clientId);return <button className={'agenda-row '+(v.id===visit?.id?'chosen':'')} key={v.id} onClick={()=>setSelected(v.id)}><img src={petImage(c.photo)} alt={c.name}/><span><strong>{c.name}</strong><small>{v.time} · {status(v.status)}</small></span><StatusIcon status={v.status}/></button>})}{!visits.length&&<Empty title={L('A little breathing room','这一天，暂时没有安排')} body={L('Try another date or add a visit.','可以切换日期或新建服务。')}/>}</div><div className="agenda-bottom"><p>{db.settings.signature}</p><PawPrint size={31} weight="fill"/><button className="text-action" onClick={()=>navigate('settings')}><Pen size={14}/>{L('Edit studio appearance','修改工作室外观')}</button></div></aside>
 {visit?<><section className="care panel"><div className="care-heading"><div><h2>{L(visit.status==='active'?'Caring for ':visit.status==='completed'?'All done, ':'Meet ',visit.status==='active'?'正在照顾':visit.status==='completed'?'已照顾好':'准备照顾')}{pet.name}</h2><p>{visit.time}–{visit.end} · {status(visit.status)}</p></div><button className="text-action" onClick={()=>setDialog({type:'handover',id:visit.clientId,visitId:visit.id})}>{L('Care guide','查看交接')}<CaretRight/></button></div><div className="pet-feature"><button className="pet-hero-button" aria-label={L('Change pet photo','更换宠物照片')} onClick={()=>editVisit(visit.id,'profile')}><img className="pet-hero" src={petImage(pet.photo)} alt={pet.name}/><span><Camera size={16}/>{L('Change photo','更换照片')}</span></button><div className="pet-summary"><h3>{pet.name}</h3><p>{pet.breed} · {pet.age}</p><div><strong>{L('A little reminder','今日重点：')}</strong><p>{visit.handover.note}</p></div></div></div>
 <div className="visit-edit-actions"><button className="outline" onClick={()=>editVisit(visit.id,'profile')}><Pen size={16}/>{L('Edit details','修改资料')}</button><button className="outline" onClick={()=>editVisit(visit.id,'time')}><Clock size={16}/>{L('Edit date & time','修改日期时间')}</button><button className="text-action" onClick={()=>editVisit(visit.id,'tasks')}>{L('Edit tasks','编辑任务')}</button></div>
 {visit.status==='pending'?<div className="start-block"><Clock size={27}/><h3>{L('One last look at the care guide.','到访前，再看一眼交接。')}</h3><p>{pet.owner} · {pet.area}<br/>{visit.handover.food}</p>{!pet.confirmed&&<p className="notice">{L('Care instructions need owner confirmation.','照顾说明尚待主人确认。')}</p>}<button className="primary" onClick={()=>patchVisit({status:'active',startedAt:timeNow()})}>{L('Start visit','开始到访')}<ArrowRight/></button></div>:<><div className="task-title"><h3>{L('Care checklist','照顾任务')}</h3><span>{visit.checks.filter(Boolean).length}/{visit.checks.length} {L('done','已完成')}</span></div><div className="task-list">{taskNames(visit.handover,lang).map((t,i)=><label className={'task-row '+(visit.checks[i]?'checked':'')} key={i}><input type="checkbox" checked={visit.checks[i]} disabled={visit.status==='completed'} onChange={()=>{const checks=[...visit.checks];checks[i]=!checks[i];patchVisit({checks})}}/><span className="check-box">{visit.checks[i]&&<Check size={16} weight="bold"/>}</span><span>{t}</span></label>)}</div><p className="hint">{L('Record what happened. Add a reason for anything unfinished.','记录真实完成情况，未完成的任务可说明原因。')}</p></>}
 </section><aside className="record panel"><div className="record-heading"><h2>{L('This little visit','本次记录')}</h2><button className="text-action" onClick={()=>editVisit(visit.id,'record')}><Pen size={16}/>{L('Edit','编辑记录')}</button></div><p className="photo-count">{visit.photos.length} {L('photos added','张照片已添加')}</p><div className="photo-grid">{visit.photos.map((p,i)=><div className="record-photo" key={i}><button onClick={()=>setDialog({type:'photo',src:p})}><img src={p} alt={L(`Visit photo ${i+1}`,`照顾照片 ${i+1}`)}/></button>{visit.status!=='completed'&&<button className="remove-photo" aria-label={L(`Remove photo ${i+1}`,`删除照片${i+1}`)} onClick={()=>patchVisit({photos:visit.photos.filter((_,j)=>j!==i)})}><X size={13}/></button>}</div>)}</div>{visit.status!=='completed'&&<button className="upload-button" disabled={uploading} onClick={()=>photoInput.current.click()}><Camera size={23}/>{uploading?L('Adding photos…','正在处理照片…'):L('Add photos','上传照片')}</button>}<input hidden ref={photoInput} type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>upload([...e.target.files])}/><div className="notes-block"><label htmlFor="notes">{L('A few observations','观察备注')}</label><div className="textarea-wrap"><textarea id="notes" maxLength={300} value={visit.notes} readOnly={visit.status==='completed'} placeholder={L('How was your little friend today?','今天它怎么样？')} onChange={e=>patchVisit({notes:e.target.value})}/><span>{visit.notes.length}/300</span></div>{visit.status!=='completed'&&<details className="exception"><summary>{L('Exception or unfinished task','异常或未完成说明')}</summary><textarea aria-label={L('Exception notes','异常说明')} value={visit.exception} maxLength={500} onChange={e=>patchVisit({exception:e.target.value})} placeholder={L('Explain what happened and what needs a follow-up.','请说明未完成的原因和需要跟进的事项。')}/></details>}</div><button className="primary full report-cta" disabled={visit.status==='pending'||uploading} onClick={()=>visit.status==='completed'?openReport(db.reports.find(r=>r.visitId===visit.id)?.id):setDialog({type:'preview',id:visit.id})}>{visit.status==='completed'?L('View care report','查看服务报告'):L('Preview care report','预览服务报告')}<ArrowRight className="mobile-only"/></button><p className="saved"><Check size={19}/>{saveError?L('Not saved','尚未保存'):L('Saved on this device','已保存在本机')} {visit.savedAt}</p></aside></>:<div className="no-visits panel"><Empty title={L('Your next visit starts here.','让下一次照顾，从这里开始。')} body={L('Add a client using one of our care templates.','从参考模板添加客户，再安排到访。')}><button className="primary" onClick={()=>navigate('clients')}>{L('Explore templates','查看模板')}</button></Empty></div>}</div>}
 {tab==='schedule'&&mobile&&<MobileSchedule lang={lang} db={db} date={date} setDate={setDate} status={status} matches={matches} onOpen={openVisit} onEdit={editVisit} onNew={date=>setDialog({type:'new',date})}/> }
 {tab==='schedule'&&!mobile&&<section className="panel schedule"><div className="section-toolbar"><div className="segmented"><button aria-label={L('Previous week','上一周')} onClick={()=>setDate(addDays(date,-7))}><CaretLeft/></button><strong>{dateText(weekOf(date)[0],lang)} — {dateText(weekOf(date)[6],lang)}</strong><button aria-label={L('Next week','下一周')} onClick={()=>setDate(addDays(date,7))}><CaretRight/></button></div><button className="outline" onClick={()=>setDate(todayDate())}>{L('Today','回到今天')}</button></div><div className="week-grid">{weekOf(date).map(d=><div className={'day-column '+(d===date?'today':'')} key={d}><header><span>{new Intl.DateTimeFormat(lang==='en'?'en-GB':'zh-CN',{weekday:'short'}).format(new Date(d+'T12:00:00'))}</span><strong>{Number(d.slice(-2))}</strong></header><div>{db.visits.filter(v=>v.date===d&&v.status!=='cancelled'&&matches(client(v.clientId))).sort((a,b)=>a.time.localeCompare(b.time)).map(v=><div className="schedule-visit-wrap" key={v.id}><button className={'schedule-visit '+v.status} key={v.id} onClick={()=>openVisit(v)}><span>{v.time}–{v.end}</span><img src={petImage((v.handover||client(v.clientId)).photo)} alt=""/><strong>{(v.handover||client(v.clientId)).name}</strong><small>{status(v.status)}</small></button><button className="schedule-edit-button" aria-label={L(`Edit visit for ${(v.handover||client(v.clientId)).name}`,`编辑${(v.handover||client(v.clientId)).name}的服务`)} onClick={()=>editVisit(v.id)}><Pen size={14}/>{L('Edit visit','编辑服务')}</button></div>)}<button className="add-slot" onClick={()=>setDialog({type:'new',date:d})}><Plus/>{L('Add visit','安排到访')}</button></div></div>)}</div></section>}
 {tab==='clients'&&<ClientHub view={clientView} setView={setClientView} lang={lang} db={db} matches={matches} onTemplate={t=>setDialog({type:'template',template:t})} onEdit={c=>setDialog({type:'editClient',clientId:c.id})} onGuide={c=>setDialog({type:'handover',id:c.id})} onSchedule={c=>setDialog({type:'new',clientId:c.id,date})}/>}
 {tab==='reports'&&<section className="panel reports-list"><div className="section-toolbar"><div className="filter-tabs">{[['all','All reports','全部报告'],['unread','Not viewed','待查看'],['read','Viewed','已查看']].map(([id,en,zh])=><button key={id} className={id===filter?'selected':''} onClick={()=>setFilter(id)}>{L(en,zh)}</button>)}</div><button className="outline" onClick={()=>setDialog({type:'export'})}><DownloadSimple/>{L('Export Excel / PDF','导出 Excel / PDF')}</button></div>{db.reports.filter(r=>matches(client(r.clientId))&&(filter==='all'||(filter==='read'?r.viewed:!r.viewed))).map(r=><button className="report-row" key={r.id} onClick={()=>openReport(r.id)}><img src={petImage(r.handover?.photo||client(r.clientId).photo)} alt=""/><div><h3>{r.name} · {L('Care report','照顾记录')}</h3><p>{dateText(r.date,lang)} · {r.time}–{r.end}</p></div><span className={'badge '+(r.viewed?'green':'amber')}>{r.viewed?L('Viewed','已查看'):L('Not viewed','待查看')}</span><CaretRight/></button>)}{!db.reports.some(r=>matches(client(r.clientId))&&(filter==='all'||(filter==='read'?r.viewed:!r.viewed)))&&<Empty title={L('No reports here yet.','还没有这一类报告。')} body={L('Finish a visit to keep a record of your care.','完成一次到访，照顾记录就会留在这里。')}/>}</section>}
 {tab==='settings'&&mobile&&<MobileSettings lang={lang} db={db} setDb={setDb} onExport={()=>setDialog({type:'export'})} download={download} notify={setToast} onPlans={()=>navigate('plans')} onLanguage={()=>{const next=lang==='en'?'zh':'en';setDb(s=>localizeDemoContent(s,next));setLang(next);}} onAbout={()=>setDialog({type:'about'})}/> }
 {tab==='settings'&&!mobile&&<Settings onExport={()=>setDialog({type:'export'})} db={db} setDb={setDb} download={download} notify={setToast} onPlans={()=>navigate('plans')} lang={lang}/>}
 {tab==='plans'&&<Plans onExport={()=>setDialog({type:'export'})} onTemplates={()=>navigate('clients')}/>}
 <footer className="site-footer"><span>{'Pawly'} · {db.settings.signature}</span><button onClick={()=>navigate('plans')}>{L('Services & exports','服务与导出')}</button><button onClick={()=>setDialog({type:'about'})}>{L('Local preview','本机体验版')}</button></footer></main>
 <nav className="mobile-nav">{[...navs,['settings','My studio','我的',GearSix]].map(([id,en,zh,Icon])=><button key={id} onClick={()=>navigate(id)} className={id===tab?'selected':''}><Icon size={23} weight={id===tab?'fill':'regular'}/><span>{L(({work:'Today',clients:'Clients',reports:'Reports',settings:'My'})[id]||en,({work:'今天',clients:'客户',reports:'报告',schedule:'排期'})[id]||zh)}</span></button>)}</nav>
 {toast&&<div className="toast" role="status"><CheckCircle size={20}/>{toast}</div>}
 {dialog?.type==='export'&&<ExportPanel state={db} lang={lang} Frame={Modal} initialFormat={dialog.format||'excel'} reportId={dialog.reportId} onClose={()=>setDialog(null)} onDone={setToast} onPlans={()=>{setDialog(null);navigate('plans')}}/>}
 {dialog?.type==='editVisit'&&<VisitEditor state={db} visitId={dialog.id} section={dialog.section} lang={lang} Frame={Modal} onClose={()=>setDialog(null)} onSave={saveEditedVisit}/> }
 {dialog?.type==='new'&&<NewVisit db={db} defaults={dialog} lang={lang} onClose={()=>setDialog(null)} onClient={()=>setDialog({type:'template',template:templates(lang)[1]})} onSave={data=>{const dates=[data.date];while(dates.at(-1)<data.through)dates.push(addDays(dates.at(-1),1));if(db.visits.some(v=>v.status!=='cancelled'&&dates.includes(v.date)&&v.time<data.end&&v.end>data.time))return L('You already have a visit at this time. Choose another slot.','这个时间段已有服务，请调整时间。');const additions=dates.map(date=>newVisit(client(data.clientId),{...data,date}));setDb(s=>({...s,visits:[...s.visits,...additions]}));setDate(data.date);setSelected(additions[0].id);navigate('work');setDialog(null);setToast(L(`${additions.length} visit(s) scheduled.`,`已安排 ${additions.length} 次到访。`));return '';}}/>}
 {['template','editClient'].includes(dialog?.type)&&<ClientEditor key={dialog.clientId||dialog.template.id} lang={lang} existing={dialog.clientId?client(dialog.clientId):null} template={dialog.template} onClose={()=>setDialog(null)} onSave={c=>{setDb(s=>saveClient(s,c));setDialog(null);setClientView('clients');navigate('clients');setToast(L('Client saved. Future visits use the updated care guide.','客户已保存，待开始的到访会使用更新后的资料。'))}}/>}
 {dialog?.type==='handover'&&<Guide pet={dialog.visitId?db.visits.find(v=>v.id===dialog.visitId).handover:client(dialog.id)} lang={lang} onClose={()=>setDialog(null)} onEdit={()=>dialog.visitId?editVisit(dialog.visitId,'tasks'):setDialog({type:'editClient',clientId:dialog.id})} onConfirm={()=>{setDb(s=>saveClient(s,{...client(dialog.id),confirmed:true}));setDialog(null);setToast(L('Owner confirmation simulated on this device.','已在本机模拟主人确认。'))}}/>}
 {dialog?.type==='preview'&&(()=>{const v=db.visits.find(v=>v.id===dialog.id),c=v.handover;return <Modal title={L('Preview care report','预览服务报告')} subtitle={L('One last check before you finish.','发布前，再检查一次真实完成情况。')} onClose={()=>setDialog(null)}><ReportContent report={{...v,name:c.name,time:v.startedAt||v.time,end:v.finishedAt||timeNow(),signature:db.settings.signature}} lang={lang}/>{v.checks.some(x=>!x)&&!v.exception.trim()&&<p className="notice"><WarningCircle/>{L('Unfinished tasks need an explanation.','有未完成任务，请返回补充原因。')}</p>}<div className="modal-actions"><button className="outline" onClick={()=>setDialog(null)}>{L('Back to edit','返回修改')}</button><button className="primary" onClick={()=>publish(v.id)}>{L('Publish report','确认发布')}<ArrowRight/></button></div></Modal>})()}
 {dialog?.type==='report'&&r&&<Modal title={dialog.owner?L('Your little friend’s update','给主人的照顾报告'):L('Care report','服务报告')} subtitle={dialog.owner?L('Owner view · Local simulation','主人视角 · 本机演示'):L('A snapshot of this visit.','本次照顾的完整记录。')} onClose={()=>setDialog(null)}><ReportContent report={r} lang={lang}/>{!dialog.owner&&r.revisions?.length>0&&<details className="revision-history"><summary>{L(`Previous versions (${r.revisions.length})`,`查看历史版本（${r.revisions.length}）`)}</summary>{r.revisions.map((old,i)=><button key={i} className="text-action" onClick={()=>setDialog({type:'oldReport',report:old})}>{L(`Version ${old.revision||i+1} · ${old.name}`,`第${old.revision||i+1}版 · ${old.name}`)}</button>)}</details>}<div className="report-feedback"><h3>{L('Owner feedback','主人反馈')}</h3>{r.reply&&<p>{r.reply}</p>}<small>{r.viewed?L('Viewed','已查看'):L('Not viewed','尚未查看')} · {r.acknowledged?L('Acknowledged','已确认收到'):L('Awaiting acknowledgement','未确认收到')}</small></div>{dialog.owner?<form onSubmit={e=>{e.preventDefault();const reply=new FormData(e.currentTarget).get('reply');setDb(s=>({...s,reports:s.reports.map(x=>x.id===r.id?{...x,viewed:true,acknowledged:true,reply:reply||x.reply}:x)}));setToast(L('Acknowledgement saved.','已确认收到这次报告。'))}}><label className="field">{L('Leave a reply','回复照顾人')}<textarea name="reply" maxLength={300}/></label><button className="primary full">{L('Thank you, received','确认收到')}</button></form>:<><div className="modal-actions wrap"><button className="outline" onClick={()=>editVisit(r.visitId,'record')}><Pen/>{L('Revise report','修订报告')}</button><button className="outline" onClick={()=>{setDialog({...dialog,owner:true});setDb(s=>({...s,reports:s.reports.map(x=>x.id===r.id?{...x,viewed:true}:x)}))}}><Eye/>{L('Owner view','主人视角')}</button><button className="outline" onClick={()=>setDialog({type:'export',format:'pdf',reportId:r.id})}><DownloadSimple/>{L('Export PDF','导出 PDF')}</button><button className="primary" onClick={()=>copy(plainReport(r,lang))}><Copy/>{L('Copy report','复制报告')}</button></div><p className="hint">{L('Copy the text to share. Online owner links and read receipts are not connected yet.','可复制文字发送。在线主人邀请和真实已读回执尚未接入。')}</p></>}</Modal>}
 {dialog?.type==='oldReport'&&<Modal title={L('Previous report · Read only','历史报告 · 只读')} onClose={()=>setDialog(null)}><ReportContent report={dialog.report} lang={lang}/></Modal>}
 {dialog?.type==='photo'&&<Modal title={L('Visit photo','照顾照片')} onClose={()=>setDialog(null)} wide><img className="lightbox-photo" src={dialog.src} alt={L('Visit photo','照顾照片')}/></Modal>}
 {dialog?.type==='copy'&&<Modal title={L('Copy report','复制报告')} onClose={()=>setDialog(null)}><textarea className="copy-fallback" readOnly value={dialog.text} onFocus={e=>e.target.select()}/></Modal>}
 {dialog?.type==='about'&&<Modal title={L('A little notebook, on this device.','这一份小本，先在本机陪伴你。')} onClose={()=>setDialog(null)}><div className="about"><PawPrint size={42} weight="duotone"/><p>{L('This working preview uses example pets and visits. Replace a sample profile or create a client from a template. Existing client details are not translated automatically when you switch language.','当前是可操作的本机体验版。示例宠物可以替换，也可从模板新建客户。切换语言不会自动翻译你已填写的客户资料。')}</p><p>{L('Records stay in this browser. Export a backup before clearing site data. The template photographs are illustrative.','记录保存在当前浏览器，清除数据前请先导出备份。模板照片仅为示例。')}</p><p>{L('Accounts, cloud sync, live owner links and payments are not connected. Basic Excel and PDF exports are free during beta.','账号、跨设备同步、在线邀请和收款尚未接入。内测期间基础 Excel 与 PDF 导出免费。')}</p></div></Modal>}
 </div>;
}
function ClientHub({lang,db,matches,onTemplate,onEdit,onGuide,onSchedule,view,setView}){
 const L=useCopy();const mine=db.clients.filter(matches);
 return <section><div className="section-toolbar"><div className="filter-tabs"><button className={view==='templates'?'selected':''} onClick={()=>setView('templates')}>{L('Care templates','参考模板')}<span className="tab-count">4</span></button><button className={view==='clients'?'selected':''} onClick={()=>setView('clients')}>{L('My clients','我的客户')}<span className="tab-count">{db.clients.length}</span></button></div><button className="outline" onClick={()=>onTemplate(templates(lang)[1])}><Plus size={18}/>{L('Add client','添加客户')}</button></div>
 {view==='templates'?<><div className="template-intro"><div><h2>{L('A starting point, never a fixed profile.','模板是起点，每一份托付都不同。')}</h2><p>{L('Choose a care routine, replace the photo and details, then save it as your client. Your template stays ready for the next little friend.','选择照顾类型，替换照片、宠物和主人信息，再保存为客户。原模板会保留，方便下次继续参考。')}</p></div><div className="template-steps"><span>01 {L('Choose','选模板')}</span><ArrowRight/><span>02 {L('Personalise','换资料')}</span><ArrowRight/><span>03 {L('Save client','存客户')}</span></div></div><div className="client-grid template-grid">{templates(lang).filter(matches).map(t=><article className="client-card panel" key={t.id}><button className="client-image" onClick={()=>onTemplate(t)}><img src={petImage(t.photo)} alt={t.title}/><span className="badge template-badge"><Stack size={12}/>{L('Editable template','可替换模板')}</span></button><div><h2>{t.title}</h2><p>{L('Example: ','示例：')}{t.name}</p><p className="client-note">{t.note}</p><footer><button className="text-action" onClick={()=>onTemplate(t)}>{L('Use this template','使用此模板')}<ArrowRight/></button></footer></div></article>)}</div><p className="template-footnote">{L('Confirm every care instruction with the owner. Example meal portions and routines are not veterinary advice.','实际照顾要求应与主人逐项确认，示例食量与照顾方式仅供填写参考。')}</p><details className="example-profiles"><summary>{L('Personalise the 4 demo profiles already on the workspace','替换工作台中已有的4个示例档案')}</summary><div className="example-profile-list">{db.clients.filter(c=>c.isExample).map(c=><button key={c.id} onClick={()=>onEdit(c)}><img src={petImage(c.photo)} alt=""/><span>{c.name}</span><Pen/></button>)}</div></details></>:<><div className="client-grid">{mine.map(c=><article className="client-card panel" key={c.id}><button className="client-image" onClick={()=>onEdit(c)}><img src={petImage(c.photo)} alt={c.name}/><span className={'badge '+(c.confirmed?'green':'amber')}>{c.confirmed?L('Guide confirmed','交接已确认'):L('Needs confirmation','交接待确认')}</span></button><div><h2>{c.name}</h2><p>{c.breed} · {c.age}{c.isExample&&<span className="sample-label">{L('Example · editable','示例 · 可修改')}</span>}</p><p className="muted"><Users size={15}/>{c.owner}<MapPin size={15}/>{c.area}</p><p className="client-note">{c.note}</p><footer><button className="text-action" onClick={()=>onEdit(c)}><Pen/>{L('Edit profile','修改资料')}</button><button className="icon-button" aria-label={L('View care guide','查看照顾档案')} onClick={()=>onGuide(c)}><FileText size={18}/><span>{L('Guide','交接')}</span></button><button className="icon-button" aria-label={L('Schedule visit','安排服务')} onClick={()=>onSchedule(c)}><CalendarBlank size={18}/><span>{L('Schedule','安排')}</span></button></footer></div></article>)}</div>{!mine.length&&<Empty title={L('Your first little friend belongs here.','从第一个真实客户开始。')} body={L('Choose a template and make it their own.','选择模板，把示例资料替换为你的客户。')}><button className="primary" onClick={()=>setView('templates')}>{L('Choose a template','选择模板')}</button></Empty>}</>}
 </section>;
}
function ClientEditor({existing,template,lang,onClose,onSave}){
 const L=useCopy();const base=existing||template;const [draft,setDraft]=useState(()=>({...base,name:existing?.name||'',owner:existing?.owner||'',area:existing?.area||'',contact:existing?.contact||'',isExample:false}));const [loading,setLoading]=useState(false),[error,setError]=useState('');const file=useRef();
 const fields=[['name','Pet name(s)','宠物名字'],['owner','Owner name','主人称呼'],['breed','Breed / description','品种 / 描述'],['age','Age','年龄'],['area','Neighbourhood','小区 / 区域'],['contact','Contact number (optional)','联系电话（选填）']];
 const careFields=[['note','A little reminder','重点提醒'],['food','Food & portions','喂养说明'],['water','Water','饮水要求'],['clean','Cleaning','清洁任务'],['care','Companionship & home checks','陪伴与居家注意']];
 return <Modal title={existing?L('Edit client details','修改客户资料'):L('Meet your next little friend','添加一份新的托付')} subtitle={existing?L('Edit the example or update a real client.','可修改示例资料，也可更新真实客户。'):L(`Starting from: ${template.title}`,`参考模板：${template.title}`)} onClose={onClose} wide><form onSubmit={e=>{e.preventDefault();if(!draft.name.trim()||!draft.owner.trim())return setError(L('Add a pet name and owner name.','请填写宠物名字和主人称呼。'));onSave(existing?{...draft,name:draft.name.trim(),owner:draft.owner.trim(),isExample:false}:makeClient(template,draft));}}>
 <div className="editor-top"><div className="editor-photo"><img src={petImage(draft.photo)} alt={L('Pet profile preview','宠物照片预览')}/><button type="button" className="photo-change" disabled={loading} onClick={()=>file.current.click()}><Camera size={17}/>{loading?L('Loading…','处理中…'):L('Replace photo','更换照片')}</button></div><div><h3>{draft.name||L('A name, a face, a few little habits.','名字、照片，还有它的小习惯。')}</h3><p className="hint">{L('Your photo replaces the sample everywhere in future visits. JPG, PNG or WebP, up to 10 MB.','上传照片后，未来到访会使用新照片。支持 JPG、PNG、WebP，最大10MB。')}</p><span className="badge amber">{L('Owner confirmation needed','需主人确认交接')}</span></div><input ref={file} hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={async e=>{const f=e.target.files[0];if(!f)return;setLoading(true);try{const photo=await compressPhoto(f,800);setDraft(d=>({...d,photo}));setError('')}catch{setError(L('Use a supported image under 10 MB.','请选择小于10MB的有效照片。'))}finally{setLoading(false);e.target.value=''}}}/></div>
 <div className="form-grid">{fields.map(([key,en,zh])=><label className="field" key={key}>{L(en,zh)}<input name={key} value={draft[key]||''} required={['name','owner'].includes(key)} maxLength={key==='area'?80:40} type={key==='contact'?'tel':'text'} placeholder={key==='name'?L(`For example, ${base.name}`,`例如：${base.name}`):undefined} onChange={e=>setDraft({...draft,[key]:e.target.value})}/></label>)}<label className="field">{L('Pet type','宠物类型')}<select name="species" value={draft.species||'cat'} onChange={e=>setDraft({...draft,species:e.target.value})}><option value="cat">{L('Cat','猫咪')}</option><option value="dog">{L('Dog','狗狗')}</option></select></label><label className="field">{L('Number of pets','宠物数量')}<input name="count" type="number" min="1" max="20" value={draft.count||1} onChange={e=>setDraft({...draft,count:Number(e.target.value)})}/></label></div><h3 className="section-spacer">{L('Their care guide','照顾说明')}</h3><p className="hint">{L('These are starting points. Adjust each instruction with the owner.','以下说明来自参考模板，请根据主人的实际要求逐项修改。')}</p><div className="care-fields">{careFields.map(([key,en,zh])=><label className="field" key={key}>{L(en,zh)}<textarea name={key} value={draft[key]||''} maxLength={500} required onChange={e=>setDraft({...draft,[key]:e.target.value})}/></label>)}</div><p className="hint">{L('Future visits receive these updates. Visits already started and published reports keep their original care snapshot.','待开始的到访会同步更新；已经开始的到访与历史报告保留原始照顾快照。')}</p>{error&&<p role="alert" className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="outline" onClick={onClose}>{L('Cancel','取消')}</button><button className="primary" disabled={loading}>{existing?L('Save changes','保存修改'):L('Save client','保存为客户')}<ArrowRight/></button></div></form></Modal>;
}
function NewVisit({db,defaults,onClose,onSave,onClient,lang}){const L=useCopy(),[error,setError]=useState('');return <Modal title={L('Plan a little visit','安排一次新的照顾')} subtitle={L('Choose a client, then find a little time for them.','选好家庭和时间，系统会生成每次到访任务。')} onClose={onClose}><form onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const validation=validateService(d);if(validation)return setError(lang==='en'?'Use valid dates (up to 31 days) and an end time after the start time.':validation);setError(onSave(d)||'')}}><label className="field">{L('Client & pet','服务家庭')}<select name="clientId" defaultValue={defaults.clientId||db.clients.find(c=>!c.isExample)?.id||db.clients[0]?.id}>{db.clients.map(c=><option key={c.id} value={c.id}>{c.name} · {c.owner}{c.isExample?L(' (example)','（示例）'):''}</option>)}</select></label><button type="button" className="text-action" onClick={onClient}><Plus/>{L('Create a client from a template','从模板添加新客户')}</button><div className="form-grid"><label className="field">{L('First visit','开始日期')}<input required name="date" type="date" defaultValue={defaults.date||RELEASE_DATE}/></label><label className="field">{L('Repeat daily until (optional)','持续至（可选）')}<input name="through" type="date"/></label><label className="field">{L('Start time','预约开始')}<input required name="time" type="time" defaultValue="13:00"/></label><label className="field">{L('End time','预约结束')}<input required name="end" type="time" defaultValue="14:00"/></label></div><p className="hint">{L('Repeat at the same time daily, for up to 31 days.','设置结束日期后，每天同一时间安排一次，最多31天。')}</p>{error&&<p role="alert" className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="outline" onClick={onClose}>{L('Not now','暂不安排')}</button><button className="primary">{L('Schedule visit','创建服务')}<ArrowRight/></button></div></form></Modal>}
function Guide({pet,lang,onClose,onEdit,onConfirm}){const L=useCopy();return <Modal title={L(`${pet.name}’s care guide`,`${pet.name}的照顾档案`)} subtitle={L(`Version ${pet.version} · ${pet.confirmed?'Confirmed':'Needs owner confirmation'}`,`交接版本 ${pet.version} · ${pet.confirmed?'已确认':'待主人确认'}`)} onClose={onClose}><div className="handover-profile"><img src={petImage(pet.photo)} alt={pet.name}/><div><h2>{pet.name}</h2><p>{pet.breed} · {pet.age}</p><p>{pet.owner} · {pet.area}</p></div></div><div className="handover-notes">{[['note','Reminder','重点提醒'],['food','Food & portions','喂养说明'],['water','Water','饮水要求'],['clean','Cleaning','清洁任务'],['care','Companionship & home','陪伴与居家注意']].map(([key,en,zh])=><section key={key}><h3>{L(en,zh)}</h3><p>{pet[key]}</p></section>)}</div>{pet.contact&&<a className="outline" href={'tel:'+pet.contact}><Phone/>{L('Call owner','联系主人')}</a>}<div className="modal-actions wrap"><button className="outline" onClick={onEdit}><Pen/>{L('Edit profile & guide','修改资料与交接')}</button>{!pet.confirmed&&<button className="primary" onClick={onConfirm}>{L('Simulate confirmation','模拟主人确认')}</button>}</div><p className="hint">{L('Confirmation is a local simulation until owner accounts are connected.','当前确认属于本机演示，真实主人确认需连接账号。')}</p></Modal>}
function ReportContent({report:r,lang}){const L=useCopy();return <div className="report-document"><div className="report-pet"><img src={petImage(r.handover?.photo)} alt={r.name}/><div><h2>{r.name} · {L('Care report','照顾记录')}</h2><p>{dateText(r.date,lang)} · {r.time}–{r.end}</p></div><PawPrint size={28} weight="fill"/></div><div className="report-checks">{taskNames(r.handover,lang).map((t,i)=><div key={i}><span>{t}</span><span className={r.checks[i]?'success':'danger'}>{r.checks[i]?<CheckCircle weight="fill"/>:<WarningCircle/>}{r.checks[i]?L('Done','已完成'):L('Not completed','未完成')}</span></div>)}</div><h3>{L('A few observations','观察记录')}</h3><p className="preline">{r.notes||L('No additional observations.','本次暂无补充备注。')}</p>{r.exception&&<div className="exception-report"><h3>{L('Exception / unfinished task','异常 / 未完成说明')}</h3><p>{r.exception}</p></div>}<div className="report-images">{r.photos.map((p,i)=><img key={i} src={p} alt={L(`Visit photo ${i+1}`,`照顾照片${i+1}`)}/>)}</div><p className="report-signature">{r.signature??L('A little visit. A lot of reassurance.','用陪伴，让它更安心。')}<PawPrint size={16}/></p></div>}
function Settings({db,setDb,download,notify,onPlans,onExport,lang}){
 const L=useCopy();const [draft,setDraft]=useState({...db.settings}),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>setDraft(d=>localizeDemoContent({...db,settings:d},lang).settings),[lang]);
 const fields=[['name','Your name','你的称呼',40],['studio','Studio name','工作室名称',60],['brandName','Studio display name (optional)','工作室展示名（选填）',24],['workTitle','Workspace welcome title','工作台欢迎语',80],['tagline','A short welcome message','欢迎语下的说明',120],['signature','Report sign-off','工作室与报告签名',100]];
 return <div className="settings-layout"><section className="panel settings-panel"><h2>{L('Studio details & appearance','工作室资料与外观')}</h2><p>{L('Your photo, name and words — all in one place.','头像、称呼、工作室名称和欢迎语，都可以在这里修改。')}</p><form onSubmit={e=>{e.preventDefault();if(!draft.name?.trim()||!draft.studio?.trim())return setError(L('Enter your name and studio name.','请填写称呼和工作室名称。'));setDb(s=>({...s,settings:{...s.settings,...Object.fromEntries(fields.map(([key])=>[key,draft[key]])),avatar:draft.avatar}}));setError('');notify(L('Your studio details are updated.','工作室资料和外观已更新。'));}}>
 <div className="settings-avatar"><PhotoEditor src={draft.avatar||'/assets/sitter.jpg'} label={L('Change avatar','更换头像')} lang={lang} onBusy={setBusy} onChange={avatar=>setDraft(d=>({...d,avatar}))}/></div>
 {fields.map(([key,en,zh,max])=><label className="field" key={key}>{L(en,zh)}<input name={key} required={['name','studio'].includes(key)} maxLength={max} value={draft[key]??''} placeholder={key==='brandName'?'Pawly':key==='workTitle'?L('Every visit, thoughtfully done.','把每一次照顾，放在心上'):undefined} onChange={e=>setDraft(d=>({...d,[key]:e.target.value}))}/></label>)}
 <p className="editor-help">{L('New reports use this sign-off. Open an older report and choose Revise report to change its sign-off.','新报告会使用这个签名；旧报告可通过“修订报告”单独更改。')}</p>{error&&<p role="alert" className="form-error">{error}</p>}<button className="primary" disabled={busy}>{L('Save studio details','保存工作室资料')}</button></form></section>
 <section className="panel settings-panel"><h2>{L('Workspace preferences','工作台偏好')}</h2><div className="setting-row"><div><h3>{L('Compact view','紧凑显示')}</h3><p>{L('Show more visits with less space.','减少列表留白，查看更多任务。')}</p></div><button className={'switch '+(db.settings.compact?'on':'')} role="switch" aria-checked={db.settings.compact} aria-label={L('Compact view','紧凑显示')} onClick={()=>setDb(s=>({...s,settings:{...s.settings,compact:!s.settings.compact}}))}><span/></button></div>
 <div className="setting-row"><div><h3>{L('Getting started guide','上手提示')}</h3><p>{L('Show the three quick actions on the workspace.','在工作台显示修改资料、调整时间和添加记录的入口。')}</p></div><button className={'switch '+(!db.settings.hideGuide?'on':'')} role="switch" aria-checked={!db.settings.hideGuide} aria-label={L('Getting started guide','上手提示')} onClick={()=>setDb(s=>({...s,settings:{...s.settings,hideGuide:!s.settings.hideGuide}}))}><span/></button></div>
 <h2 className="section-spacer">{L('Export & backup','导出与备份')}</h2><p>{L('Download a spreadsheet for organising, or a photo report to send to an owner.','整理排期用 Excel，发给主人用 PDF。')}</p><button className="primary" onClick={onExport}><DownloadSimple/>{L('Export Excel / PDF','导出 Excel / PDF')}</button><h3 className="section-spacer">{L('Original data backup','原始数据备份')}</h3><p>{L('Your data stays in this browser. The backup includes clients, visits, photos and previous report versions.','当前数据保存在本机浏览器，备份包含客户、服务、照片和报告历史版本。')}</p><button className="outline" onClick={()=>download('pawly-backup.json',JSON.stringify(db,null,2))}><DownloadSimple/>{L('Download JSON backup','下载 JSON 备份')}</button><div className="local-note"><SealCheck size={24}/><div><h3>{L('Services & exports','服务与导出')}</h3><p>{L('Basic exports are free during beta. See what is available and what is planned.','基础导出在内测期间免费，可查看已实现功能与后续规划。')}</p><button className="text-action" onClick={onPlans}>{L('View service plans','查看服务规划')}<ArrowRight/></button></div></div></section></div>;
}
function Plans({onTemplates,onExport}){
 const L=useCopy();
 const now=[L('Editable clients, pet photos and care instructions','客户资料、宠物照片与照顾说明修改'),L('Visit schedules, tasks and photo records','服务排期、任务清单与照片记录'),L('Excel export with four organised sheets','Excel 四张数据表，支持筛选与编辑'),L('Individual PDF reports with photos','带照片的单份 PDF 照顾报告'),L('Original data backup and report revisions','原始数据备份与报告历史版本')];
 const later=[L('Combine many reports into one export','多份报告批量合并导出'),L('More branded layouts and custom templates','更多品牌排版与自定义模板'),L('Cloud accounts and cross-device access','云端账号与跨设备访问'),L('Team scheduling and member permissions','团队排期与成员权限')];
 return <section className="beta-services"><div className="beta-intro"><span className="badge green">{L('Free beta','内测免费')}</span><h2>{L('Start with the care. Keep the useful records.','先把照顾做好，把记录留下。')}</h2><p>{L('Use the current features free during beta. There is no checkout, automatic renewal or payment collection.','内测期间，已实现的功能免费使用。目前没有结账、自动续费或扣款。')}</p></div><div className="beta-columns"><section className="beta-current"><h3>{L('Available now','现在就能使用')}</h3><ul>{now.map(t=><li key={t}><CheckCircle size={20}/><span>{t}</span></li>)}</ul><div className="beta-actions"><button className="primary" onClick={onExport}><DownloadSimple/>{L('Export Excel or PDF','导出 Excel / PDF')}</button><button className="outline" onClick={onTemplates}>{L('Manage clients','管理客户')}<ArrowRight/></button></div><p className="editor-help">{L('Records stay in this browser. Excel is for organising; PDF is for sharing a finished report. Keep a JSON backup for the original data.','记录仍保存在当前浏览器。Excel 用于整理数据，PDF 用于发送报告；原始数据可另存 JSON 备份。')}</p></section><section className="beta-future"><span className="badge">{L('Not available yet','尚未开放')}</span><h3>{L('Possible paid services, after validation','后续验证的增值服务')}</h3><p>{L('We will test these with regular users before deciding what to build and charge for.','先观察真实使用需求，再决定开发范围与收费方式。')}</p><ul>{later.map(t=><li key={t}>{t}</li>)}</ul><p className="editor-help">{L('Prices and launch dates are not set. Current page access does not include these planned services.','价格和上线时间尚未确定，以上功能当前不能购买或使用。')}</p></section></div><div className="beta-faq"><h3>{L('A few clear answers','关于免费与付费')}</h3><details><summary>{L('Is a membership required to export?','导出文件需要开通会员吗？')}</summary><p>{L('No. Excel and individual PDF exports are free during beta. Future charges will be shown before purchase.','不需要。内测期间 Excel 与单份 PDF 导出免费。未来若提供收费服务，会在购买前明确说明。')}</p></details><details><summary>{L('Can I pay for cloud sync or team access now?','现在能购买云同步和团队协作吗？')}</summary><p>{L('Not yet. Those services need real accounts, cloud storage, permissions and a verified payment system.','暂时不能。这些服务还需要接通真实账号、云端存储、权限和支付系统。')}</p></details><details><summary>{L('Is an Excel file the same as a backup?','Excel 和原始备份有什么区别？')}</summary><p>{L('Excel contains readable tables of current records. The JSON backup retains photos and previous report versions; restoring backups in the app is not supported yet.','Excel 是方便阅读和整理的最新记录表。JSON 备份保留照片数据与历史报告版本；目前尚未提供页面内导入恢复功能。')}</p></details></div></section>;
}
